import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { useNotifications } from '@/components/ui/notifications';
import { api } from '@/lib/api-client';
import { MutationConfig } from '@/lib/react-query';
import { Team } from '@/types/api';

import { getTeamsQueryOptions } from './get-teams';

export const updateTeamInputSchema = z.object({
  name: z.string().min(1, 'Required'),
});

export type UpdateTeamInput = z.infer<typeof updateTeamInputSchema>;

export const updateTeam = ({
  teamId,
  data,
}: {
  teamId: string;
  data: UpdateTeamInput;
}): Promise<Team> => {
  return api.patch(`/teams/${teamId}`, data);
};

type UseUpdateTeamOptions = {
  mutationConfig?: MutationConfig<typeof updateTeam>;
};

export const useUpdateTeam = ({ mutationConfig }: UseUpdateTeamOptions = {}) => {
  const queryClient = useQueryClient();
  const { addNotification } = useNotifications();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      queryClient.invalidateQueries({
        queryKey: getTeamsQueryOptions().queryKey,
      });
      addNotification({
        type: 'success',
        title: 'Team Updated',
      });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: updateTeam,
  });
};
EOF
cat > features/teams/components/update-team.tsx <<'EOF'
import { Pen } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Form, FormDrawer, Input } from '@/components/ui/form';
import { Team } from '@/types/api';

import { updateTeamInputSchema, useUpdateTeam } from '../api/update-team';

type UpdateTeamProps = {
  team: Team;
};

export const UpdateTeam = ({ team }: UpdateTeamProps) => {
  const updateTeamMutation = useUpdateTeam();

  return (
    <FormDrawer
      isDone={updateTeamMutation.isSuccess}
      triggerButton={
        <Button icon={<Pen className="size-4" />} size="sm">
          Rename
        </Button>
      }
      title="Rename Team"
      submitButton={
        <Button
          form="update-team"
          type="submit"
          size="sm"
          isLoading={updateTeamMutation.isPending}
        >
          Submit
        </Button>
      }
    >
      <Form
        id="update-team"
        onSubmit={(values) => {
          updateTeamMutation.mutate({ teamId: team.id, data: values });
        }}
        options={{ defaultValues: { name: team.name } }}
        schema={updateTeamInputSchema}
      >
        {({ register, formState }) => (
          <Input
            label="Team Name"
            error={formState.errors['name']}
            registration={register('name')}
          />
